{'offer_price_type': [{'quote': 'We are offering to purchase shares of common stock at a price of $9.43 per share (the “Purchase Price”).', 'location': 'SUMMARY TERM SHEET', 'relevance_score': 5}], 'offer_price': [{'quote': 'We are offering to purchase shares of common stock at a price of $9.43 per share (the “Purchase Price”).', 'location': 'SUMMARY TERM SHEET', 'relevance_score': 5}], 'offer_price_currency': [{'quote': 'Unless otherwise specifically indicated, all references to “USD” or “$” shall refer to the lawful currency of the United States.', 'location': 'EXHIBIT (a)(1)(F)', 'relevance_score': 5}, {'quote': 'We are offering to purchase shares of common stock at a price of $9.43 per share (the “Purchase Price”).', 'location': 'SUMMARY TERM SHEET', 'relevance_score': 5}], 'offer_price_basis': [{'quote': 'We are offering to purchase shares of common stock at a price of $9.43 per share (the “Purchase Price”).', 'location': 'SUMMARY TERM SHEET', 'relevance_score': 5}], 'offer_price_qualifications': [{'quote': 'If your shares are purchased in the Offer, we will pay you the Purchase Price, in cash, less any applicable withholding taxes and without interest, promptly after the expiration of the Offer.', 'location': 'SUMMARY TERM SHEET', 'relevance_score': 5}], 'expiration_date': [{'quote': 'THE OFFER AND WITHDRAWAL RIGHTS WILL EXPIRE AT 5:00 P.M., NEW YORK CITY TIME, ON FEBRUARY 2, 2026, UNLESS THE OFFER IS EXTENDED OR TERMINATED (THE “EXPIRATION TIME”)', 'location': 'EXHIBIT (a)(1)(F)', 'relevance_score': 5}], 'withdrawal_deadline': [{'quote': 'Shares tendered in the Offer may be withdrawn at any time prior to the Expiration Time. In addition, unless the Company has already accepted your tendered shares for payment, you may withdraw your tendered shares at any time after 5:00 p.m., New York City time, on February 25, 2026, which is 40 business days after the commencement of the offer.', 'location': '4. Withdrawal Rights', 'relevance_score': 5}, {'quote': 'THE OFFER AND WITHDRAWAL RIGHTS WILL EXPIRE AT 5:00 P.M., NEW YORK CITY TIME, ON FEBRUARY 2, 2026, UNLESS THE OFFER IS EXTENDED OR TERMINATED (THE “EXPIRATION TIME”)', 'location': 'EXHIBIT (a)(1)(F)', 'relevance_score': 5}], 'settlement_date': [{'quote': 'Upon the terms and subject to the conditions of the Offer, promptly following the Expiration Time, we will accept for payment and pay for all of the shares accepted for payment pursuant to the tender offer.', 'location': '5. Purchase of Shares and Payment of Purchase Price', 'relevance_score': 5}, {'quote': 'In all cases, payment for shares tendered and accepted for payment pursuant to the Offer will be made promptly, taking into account any time necessary to determine any proration and any drawing of lots for conditional tenders, but only after timely receipt by the Depositary of (1) certificates for shares, or a timely book-entry confirmation of the deposit of shares into the Depositary’s account at DTC, (2) a validly completed and duly executed Letter of Transmittal including any required signature guarantees, or, in the case of a book-entry transfer, an Agent’s Message, and (3) any other required documents.', 'location': '5. Purchase of Shares and Payment of Purchase Price', 'relevance_score': 5}], 'effective_date': [], 'subject_company': [{'quote': 'Mount Logan Capital Inc.
(Name of Subject Company (Issuer) and Filing Person (Offeror))', 'location': 'SCHEDULE TO/A', 'relevance_score': 5}], 'bidder': [{'quote': 'Mount Logan Capital Inc.
(Name of Subject Company (Issuer) and Filing Person (Offeror))', 'location': 'SCHEDULE TO/A', 'relevance_score': 5}], 'parent': [], 'acquisition_subsidiary': [], 'dealer_manager': [{'quote': 'We have retained Ladenburg Thalmann & Co. Inc. to act as the Dealer Manager, Alliance Advisors, LLC, to act as Information Agent and Odyssey Transfer and Trust Company, to act as Depositary in connection with the Offer.', 'location': '16. Fees and Expenses; Information Agent; Dealer Manager; Depositary', 'relevance_score': 5}], 'depositary': [{'quote': 'We have retained Ladenburg Thalmann & Co. Inc. to act as the Dealer Manager, Alliance Advisors, LLC, to act as Information Agent and Odyssey Transfer and Trust Company, to act as Depositary in connection with the Offer.', 'location': '16. Fees and Expenses; Information Agent; Dealer Manager; Depositary', 'relevance_score': 5}], 'information_agent': [{'quote': 'We have retained Ladenburg Thalmann & Co. Inc. to act as the Dealer Manager, Alliance Advisors, LLC, to act as Information Agent and Odyssey Transfer and Trust Company, to act as Depositary in connection with the Offer.', 'location': '16. Fees and Expenses; Information Agent; Dealer Manager; Depositary', 'relevance_score': 5}], 'other_parties': [], 'event_status': [{'quote': 'This Amended Offer to Purchase, dated January 13, 2026, amends and restates in full the previously issued Offer to Purchase, dated December 29, 2025.', 'location': 'EXPLANATORY NOTE', 'relevance_score': 5}], 'event_status_details': [{'quote': 'This Amended Offer to Purchase, dated January 13, 2026, amends and restates in full the previously issued Offer to Purchase, dated December 29, 2025. The changes reflected herein are intended to provide clarifying revisions to certain procedural requirements relating to the tender offer and to certain statements regarding forward-looking information.', 'location': 'EXPLANATORY NOTE', 'relevance_score': 5}], 'minimum_tender_condition': [{'quote': 'The Offer is not conditioned upon any minimum number of shares being tendered.', 'location': 'SUMMARY TERM SHEET', 'relevance_score': 5}], 'proration_terms': [{'quote': 'Upon the terms and subject to the conditions of the Offer, if 1,590,668 shares (the “Maximum Purchase Amount”) or fewer are validly tendered and not validly withdrawn, we will buy all shares validly tendered and not validly withdrawn. Upon the terms and subject to the conditions of the Offer, if more than the Maximum Purchase Amount is validly tendered and not validly withdrawn prior to the Expiration Time, we will purchase shares in the following order of priority (subject to provisions relating to the “round lots” requirement):', 'location': '1. Number of Shares; Purchase Price; Proration', 'relevance_score': 5}, {'quote': 'All tendered shares (other than conditionally tendered shares for which the condition was not satisfied) validly tendered and not validly withdrawn prior to the Expiration Time, on a pro rata basis if necessary, based on the number of shares tendered by each shareholder, with appropriate adjustments to avoid the purchase of fractional shares, until we have purchased the Maximum Purchase Amount.', 'location': '1. Number of Shares; Purchase Price; Proration', 'relevance_score': 5}, {'quote': 'Only tenders that are “round lots” of 100 shares, or multiples thereof, will be accepted; provided, however, that shareholders owning fewer than an aggregate of 100 shares may tender all of their shares. Any tender for fewer than 100 shares, or for an amount that is not a multiple of 100 shares, other than by holders of fewer than an aggregate of 100 shares, will be rejected.', 'location': '1. Number of Shares; Purchase Price; Proration', 'relevance_score': 5}, {'quote': 'If the effect of this preliminary proration would be to reduce the number of shares to be purchased from any tendering shareholder below the minimum number specified by that shareholder, the shares conditionally tendered will automatically be regarded as withdrawn (except as provided in the next paragraph).', 'location': '6. Conditional Tender of Shares', 'relevance_score': 5}, {'quote': 'If the withdrawal of conditional tenders would cause the total number of shares to be purchased to fall below the Maximum Purchase Amount, then, to the extent feasible, we may select enough of the shares conditionally tendered that would otherwise have been withdrawn to permit us to purchase such number of shares. In selecting among the conditional tenders, we may select by random lot, treating all tenders by a particular shareholder as a single lot, and will limit our purchase in each case to the designated minimum number of shares to be purchased. To be eligible for purchase by random lot, shareholders whose shares are conditionally tendered must have validly tendered all of their shares.', 'location': '6. Conditional Tender of Shares', 'relevance_score': 5}], 'tendering_conditions': [{'quote': 'For shares to be tendered validly in the Offer:
•the shares offered must be “round lots” of 100 shares, or multiples thereof; provided, however, that shareholders owning fewer than an aggregate of 100 shares may tender all of their shares;
•the certificates for our common stock, or confirmation of receipt of the shares pursuant to the procedure for book-entry transfer set forth below, together with a validly completed and duly executed Letter of Transmittal, including any required signature guarantees, or an Agent’s Message (as defined below) in the case of a book-entry transfer, and any other documents required by the Letter of Transmittal, must be received prior to the Expiration Time by the Depositary at its address set forth on the back cover page of this Offer to Purchase; or
•the tendering shareholder must, prior to the Expiration Time, comply with the guaranteed delivery procedure set forth below.', 'location': '3. Procedures for Tendering Shares', 'relevance_score': 5}, {'quote': 'Shareholders holding shares in a brokerage account or otherwise through a broker, dealer, commercial bank, trust company or other nominee, must contact their broker, dealer, commercial bank, trust company or other nominee in order to tender their shares.', 'location': '3. Procedures for Tendering Shares', 'relevance_score': 5}, {'quote': 'Shareholders may tender shares subject to the condition that all or a specified minimum number of shares be purchased. Any shareholder desiring to make such a conditional tender should so indicate in the section entitled “Conditional Tender” in the Letter of Transmittal and, if applicable, in the Notice of Guaranteed Delivery.', 'location': '3. Procedures for Tendering Shares', 'relevance_score': 5}, {'quote': 'If a shareholder wishes to tender shares in the Offer and the shareholder’s share certificates are not immediately available or cannot be delivered to the Depositary prior to the Expiration Time (or the procedures for book-entry transfer cannot be completed on a timely basis), or if time will not permit delivery of all required documents to the Depositary prior to the Expiration Time, the shares may still be tendered if all of the following conditions are satisfied:
•the tender is made by or through an Eligible Institution;
•the Depositary receives by mail or courier, prior to the Expiration Time, a validly completed and duly executed Notice of Guaranteed Delivery in the form the Company has provided with this Offer to Purchase, including (where required) a signature guarantee by an Eligible Institution in the form set forth in the Notice of Guaranteed Delivery; and
•the certificates for all tendered shares, in proper form for transfer (or confirmation of book-entry transfer of the shares into the Depositary’s account at DTC), together with a validly completed and duly executed Letter of Transmittal, or an Agent’s Message in the case of a book-entry transfer, and any required signature guarantees and other documents required by the Letter of Transmittal, are received by the Depositary within two business days after the Expiration Time.', 'location': '3. Procedures for Tendering Shares', 'relevance_score': 5}, {'quote': 'The Company reserves the absolute right to reject any or all tenders of any shares that it determines are not in proper form or the acceptance for payment of or payment for which it determines may be unlawful. The Company also reserves the absolute right to waive any defect or irregularity in any tender with respect to any particular shares, whether or not it waives similar defects or irregularities in the case of any other shareholder.', 'location': '3. Procedures for Tendering Shares', 'relevance_score': 5}], 'security_description': [{'quote': 'Mount Logan Capital Inc., a Delaware corporation (the “Company,” “we,” or “us”), is offering to purchase your shares of our common stock at a price of $9.43 per share (the “Purchase Price”) in cash, less any applicable withholding taxes and without interest, on the terms and subject to the conditions set forth in this Amended Offer to Purchase (as it may be further amended and supplemented from time to time, the “Offer to Purchase”) and the related Amended Letter of Transmittal (as it may be further amended and supplemented from time to time, the “Letter of Transmittal”) (which together, as they may be amended and supplemented from time to time, constitute the “Offer”). Unless the context otherwise requires, all references to “common stock” and “shares” shall refer to the shares of common stock, par value $0.001 per share, of the Company.', 'location': 'EXHIBIT (a)(1)(F)', 'relevance_score': 5}], 'available_options': [{'quote': 'You do not have to tender all of the shares that you own to participate in the Offer.', 'location': 'SUMMARY TERM SHEET', 'relevance_score': 5}, {'quote': 'Accordingly, a shareholder may tender shares subject to the condition that all or a specified minimum number of the shareholder’s shares tendered must be purchased if any shares tendered are purchased.', 'location': '6. Conditional Tender of Shares', 'relevance_score': 5}, {'quote': 'Only tenders that are “round lots” of 100 shares, or multiples thereof, will be accepted; provided, however, that shareholders owning fewer than an aggregate of 100 shares may tender all of their shares.', 'location': '1. Number of Shares; Purchase Price; Proration', 'relevance_score': 5}], 'default_option': [{'quote': 'Unless this box has been checked and a minimum specified, the shareholder’s tender will be deemed unconditional.', 'location': 'PART B', 'relevance_score': 5}], 'financial_terms': [{'quote': 'We are offering to purchase, at the Purchase Price, up to $15 million of our shares, or approximately 1,590,668 shares of our outstanding common stock, validly tendered in the Offer and not validly withdrawn, which represents approximately 12% of the total number of shares issued and outstanding as of December 26, 2025.', 'location': 'SUMMARY TERM SHEET', 'relevance_score': 5}, {'quote': 'We anticipate using funds available from cash and cash equivalents to purchase the shares tendered in the Offer and to pay fees and expenses related to the Offer.', 'location': '9. Source and Amount of Funds', 'relevance_score': 5}, {'quote': 'The Information Agent, the Dealer Manager and the Depositary will each receive reasonable and customary fees for their respective services, will be reimbursed by us for reasonable out-of-pocket expenses incurred in connection with the Offer and will be indemnified against certain liabilities in connection with the Offer, including certain liabilities under the federal securities laws. In addition, we will incur reasonable and customary fees related to SEC filings and legal and accounting services.', 'location': '16. Fees and Expenses; Information Agent; Dealer Manager; Depositary', 'relevance_score': 5}], 'conditions_restrictions': [{'quote': 'The Offer is not conditioned upon any financing.', 'location': 'SUMMARY TERM SHEET', 'relevance_score': 5}, {'quote': 'Notwithstanding any other provisions of the Offer, we will not be required to accept for payment, purchase or pay for any shares tendered, and may terminate or amend the Offer or may postpone the acceptance for payment of, or the purchase of or the payment for shares tendered, subject to the rules under the Exchange Act, if at any time prior to the Expiration Time, any of the following events or circumstances shall have occurred (or shall have been reasonably determined by us to have occurred):', 'location': '7. Conditions of the Offer', 'relevance_score': 5}, {'quote': 'Each of the conditions referred to above is for our sole benefit and may be asserted or waived by us, in whole or in part, prior to the Expiration Time.', 'location': '7. Conditions of the Offer', 'relevance_score': 5}, {'quote': 'We expressly reserve the right, in our sole discretion and subject to applicable law, at any time and from time to time, and regardless of whether or not any of the events set forth in Section 7 shall have occurred or shall be deemed by us to have occurred, to extend the period of time the Offer is open and delay acceptance for payment of, and payment for, any shares by giving oral or written notice of such extension to the Depositary and making a public announcement of such extension.', 'location': '15. Extension of the Offer Termination or Amendment', 'relevance_score': 5}, {'quote': 'Subject to compliance with applicable law, we further reserve the right, in our sole discretion, to amend the Offer in any respect (including, without limitation, by decreasing or increasing the consideration per share offered pursuant to the Offer to shareholders or by decreasing or increasing the aggregate purchase price of shares being sought in the Offer).', 'location': '15. Extension of the Offer Termination or Amendment', 'relevance_score': 5}, {'quote': 'We are not making the Offer to, and will not accept any tendered shares from, shareholders in any jurisdiction where it would be illegal to do so. However, we may, at our discretion, take any actions necessary for us to make the Offer to shareholders in any such jurisdiction.', 'location': 'IMPORTANT', 'relevance_score': 5}]}
